def table(rows,keys):
    if not rows:return 'NOT_EXECUTED / no supported rows.\n'
    def value(v):
        if v is None:return 'NOT_DEFINED'
        if isinstance(v,float):return f'{v:.6f}'
        if isinstance(v,(list,dict)):v=json.dumps(v,ensure_ascii=False,sort_keys=True)
        return str(v).replace('|','/').replace('\n',' ')
    return '| '+' | '.join(keys)+' |\n| '+' | '.join('---' for _ in keys)+' |\n'+''.join('| '+' | '.join(value(r.get(k,'UNKNOWN')) for k in keys)+' |\n' for r in rows)

def jsonblock(data):return '```json\n'+json.dumps(data,ensure_ascii=False,indent=2,sort_keys=True)+'\n```\n'

def history_sections(text):
    pieces=re.split(r'^## (\d+)\. .*?\n',text,flags=re.M)
    return {int(pieces[i]):pieces[i+1].strip() for i in range(1,len(pieces),2)}

def verify_statuses(inventory):
    if inventory['confirmation']!='NOT_LOCKED' or inventory['C2']!='MULTI_SEED_STANDARD_BASELINES; NOVELTY_NOT_ESTABLISHED' or inventory['C3']!='DEFERRED':raise ValueError('Unsupported scientific status promotion')
    ids=[r['experiment_id'] for r in inventory['experiments']]
    if len(ids)!=len(set(ids)):raise ValueError('Duplicate experiment IDs')
    aggregates=inventory['phase7']['statistics']['seed_aggregates']
    if {r['method'] for r in aggregates}!={'H0','H1','H2','H3','H4'} or any(r['seeds']<3 for r in aggregates):raise ValueError('Multi-seed status requires the actual five-method three-seed matrix')

